using System;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEngine.Events;using UnityEngine.EventSystems;using TMPro;using MDPro3.UI;using MDPro3.UI.ServantUI;using Il2CppInterop.Runtime;using UObject=UnityEngine.Object;
namespace DuelStructure {
 static class EditorMenu {
  static MainMenuUI ui;static SelectionButton_MainMenu entry;static ScrollRect scroll;static RectTransform viewport,content;static IntPtr selected;static float menuRow,lastHeight=-1;
  static T Add<T>(GameObject go) where T:Component=>go.AddComponent(Il2CppType.Of<T>()).Cast<T>();
  static RectTransform Node(string name,Transform parent){var go=new GameObject(name);var rect=Add<RectTransform>(go);rect.SetParent(parent,false);return rect;}
  public static bool Ready=>entry!=null&&entry.gameObject.activeInHierarchy&&scroll!=null;
  public static bool EntryInteractable=>entry.GetComponent<Button>().interactable;
  public static string EntryColors=>string.Join("/",entry.GetComponentsInChildren<TextMeshProUGUI>(true).Select(t=>t.color.r+","+t.color.g+","+t.color.b+","+t.color.a));
  public static void ProbePointerExit()=>entry.OnPointerExit(new PointerEventData(EventSystem.current));
  public static void Click()=>entry.GetComponent<Button>().onClick.Invoke();
  public static bool ScrollWorks(){if(scroll==null||content.rect.height<=viewport.rect.height)return false;scroll.verticalNormalizedPosition=0;bool moved=content.anchoredPosition.y>1;scroll.verticalNormalizedPosition=1;return moved;}
  public static void Tick(){var menu=MDPro3.Program.instance?.menu;if(menu==null||menu.servantUI==null||!menu.showing||menu.inTransition)return;var current=menu.GetUI<MainMenuUI>();if(ui==null||ui.Pointer!=current.Pointer){ui=current;Install();}if(entry==null)return;RefreshViewport();bool available=menu.showing&&!EditorBehaviour.PanelOpen;if(entry.GetComponent<Button>().interactable!=available)entry.SetInteractable(available);var active=EventSystem.current?.currentSelectedGameObject;if(active==null||!active.transform.IsChildOf(content)||active.Pointer==selected)return;selected=active.Pointer;var rect=active.GetComponent<RectTransform>();if(rect==null)return;float top=-rect.anchoredPosition.y,bottom=top+rect.rect.height,offset=content.anchoredPosition.y;if(top<offset)content.anchoredPosition=new Vector2(content.anchoredPosition.x,top);else if(bottom>offset+viewport.rect.height)content.anchoredPosition=new Vector2(content.anchoredPosition.x,bottom-viewport.rect.height);}
  static Vector2 ScreenPoint(Vector3 local)=>RectTransformUtility.WorldToScreenPoint(MDPro3.Program.instance.camera_.cameraUI,viewport.TransformPoint(local));
  static void RefreshViewport(){if(viewport==null||scroll==null)return;var top=ScreenPoint(Vector3.zero);float pixels=Math.Abs(ScreenPoint(Vector3.up).y-top.y);if(pixels<.001f)return;float height=Math.Max(menuRow,top.y/pixels-70);if(Math.Abs(height-lastHeight)<.1f)return;float position=scroll.verticalNormalizedPosition;scroll.StopMovement();viewport.sizeDelta=new Vector2(viewport.sizeDelta.x,height);Canvas.ForceUpdateCanvases();scroll.verticalNormalizedPosition=position;lastHeight=height;selected=IntPtr.Zero;}
  public static bool LayoutFitsScreen(){Canvas.ForceUpdateCanvases();RefreshViewport();var top=ScreenPoint(Vector3.zero);var bottom=ScreenPoint(new Vector3(0,-viewport.rect.height,0));Plugin.Instance.Log.LogInfo("MENU_RESIZE size="+Screen.width+"x"+Screen.height+" top="+top+" bottom="+bottom+" height="+viewport.rect.height);return top.x>=0&&top.x<Screen.width*.15f&&top.y<=Screen.height&&top.y>Screen.height*.7f&&bottom.y>=0&&bottom.y<Screen.height*.2f;}
  static void Install(){Canvas.ForceUpdateCanvases();var buttons=ui.GetComponentsInChildren<SelectionButton_MainMenu>(true).ToArray();if(buttons.Length<2)return;var parent=buttons[0].transform.parent;buttons=buttons.Where(b=>b.transform.parent.Pointer==parent.Pointer).OrderBy(b=>b.transform.GetSiblingIndex()).ToArray();if(buttons.Length<2)return;var first=buttons[0].GetComponent<RectTransform>();var last=buttons[buttons.Length-1].GetComponent<RectTransform>();float row=Math.Abs(first.anchoredPosition.y-buttons[1].GetComponent<RectTransform>().anchoredPosition.y);if(row<20)row=Math.Max(80,first.rect.height+20);float width=Math.Max(450,buttons.Max(b=>b.GetComponent<RectTransform>().rect.width));var screen=RectTransformUtility.WorldToScreenPoint(MDPro3.Program.instance.camera_.cameraUI,first.TransformPoint(new Vector3(first.rect.xMin,first.rect.yMax,0)));var root=ui.GetComponent<RectTransform>();var local=root.InverseTransformPoint(first.TransformPoint(new Vector3(first.rect.xMin,first.rect.yMax,0)));float scale=first.GetComponentInParent<Canvas>().rootCanvas.scaleFactor;float height=Math.Max(row*3,(screen.y-70)/Math.Max(.01f,scale));menuRow=row;
   var clone=UObject.Instantiate(buttons[2< buttons.Length?2:0].gameObject,parent);clone.name="DuelStructureMainMenuEntry";entry=clone.GetComponent<SelectionButton_MainMenu>();entry.m_Manager=clone.GetComponent<YgomSystem.ElementSystem.ElementObjectManager>();entry.m_Selectable=clone.GetComponent<Selectable>();entry.m_Hover=null;entry.m_SelectCursorOffset=null;entry.m_Corner=null;entry.m_Arrow=null;entry.m_ButtonText=null;entry.textTitle=null;entry.GetComponent<Button>().onClick=new Button.ButtonClickedEvent();entry.clickEvent=new SelectionButtonClickEvent();entry.SetToResponser=false;foreach(var text in clone.GetComponentsInChildren<TextMeshProUGUI>(true))text.text="决构编辑对局";foreach(var text in clone.GetComponentsInChildren<UnityEngine.UI.Text>(true))text.text="决构编辑对局";entry.SetClickEvent((UnityAction)(Action)EditorBehaviour.OpenSetup);Plugin.Instance.Log.LogInfo("EDITOR_MENU first screen="+screen+" local="+local+" first anchors="+first.anchorMin+" / "+first.anchorMax);
   var layout=parent.GetComponent<LayoutGroup>();if(layout!=null)layout.enabled=false;
   viewport=Node("DuelStructureMainMenuViewport",parent);viewport.anchorMin=first.anchorMin;viewport.anchorMax=first.anchorMax;viewport.pivot=new Vector2(0,1);viewport.anchoredPosition=first.anchoredPosition+new Vector2(first.rect.xMin,first.rect.yMax);viewport.sizeDelta=new Vector2(width+35,height);var image=Add<Image>(viewport.gameObject);image.color=Color.clear;image.raycastTarget=true;Add<RectMask2D>(viewport.gameObject);
   content=Node("MainMenuOptions",viewport);content.anchorMin=content.anchorMax=new Vector2(0,1);content.pivot=new Vector2(0,1);content.anchoredPosition=Vector2.zero;content.sizeDelta=new Vector2(width,(buttons.Length)*row+first.rect.height);
   var list=buttons.ToList();list.Insert(Math.Min(3,list.Count),entry);for(int i=0;i<list.Count;i++){var rect=list[i].GetComponent<RectTransform>();rect.SetParent(content,false);rect.anchorMin=rect.anchorMax=new Vector2(0,1);rect.pivot=new Vector2(0,1);rect.anchoredPosition=new Vector2(0,-i*row);rect.sizeDelta=new Vector2(width,first.rect.height);var select=list[i].GetComponent<Selectable>();var nav=select.navigation;nav.mode=Navigation.Mode.Explicit;nav.selectOnUp=i>0?list[i-1].GetComponent<Selectable>():null;nav.selectOnDown=i+1<list.Count?list[i+1].GetComponent<Selectable>():null;select.navigation=nav;}
   scroll=Add<ScrollRect>(viewport.gameObject);scroll.viewport=viewport;scroll.content=content;scroll.horizontal=false;scroll.vertical=true;scroll.movementType=ScrollRect.MovementType.Clamped;scroll.scrollSensitivity=65;scroll.inertia=true;scroll.verticalNormalizedPosition=1;lastHeight=-1;RefreshViewport();
   Plugin.Instance.Log.LogInfo("EDITOR_MENU installed options="+list.Count+" viewport="+viewport.rect+" content="+content.rect+" parent="+parent.name);
  }
 }
}
